INSERT INTO faqs (question, answer, sort_order) VALUES
  ('Do you visit the site before quoting?', 'Yes. We inspect the site so our quote is accurate. Book a site inspection online.', 0),
  ('Can you work with my architect''s drawings?', 'Yes. We can build from your approved drawings or prepare drawings for you.', 1),
  ('How do payments work?', 'Payments are made in agreed stages as work progresses, so you only pay for work done.', 2),
  ('How do I know how the project is going?', 'You get regular progress reports with photos, and you''re welcome to visit the site.', 3),
  ('Do you handle approvals?', 'We can help prepare documents for building approvals. Ask us about your location.', 4);
